async function get(url, as = 'json') {
  for (let i = 0; i < 4; i++) {
    try {
      const r = await fetch(url);
      if (!r.ok) throw new Error(`${r.status} ${url}`);
      return as === 'json' ? r.json() : Buffer.from(await r.arrayBuffer());
    } catch (e) { if (i === 3) throw e; }
  }
